INSERT INTO transactions (type, account_id, category_id, related_account_id, amount, counterparty, description, occurred_at, source_message_id)
SELECT s.type, a.id, c.id, dst.id, s.amount, s.counterparty, s.description, s.occurred_at, s.source_message_id
FROM seed s
JOIN accounts a ON a.name = s.account_name
LEFT JOIN categories c ON c.name = s.category_name AND c.type = s.type
LEFT JOIN accounts dst ON dst.name = s.destination_name
WHERE (s.type = 'transfer' AND dst.id IS NOT NULL AND dst.id <> a.id OR s.type IN ('income', 'expense') AND c.id IS NOT NULL)
AND NOT EXISTS (SELECT 1 FROM transactions t WHERE t.source_message_id = s.source_message_id);

